    public class LocalFValueHandle extends FValueHandle{
        int offset;

        public void checkValue(FValue val) {
            mv.visitVarInsn(Opcodes.ALOAD, offset);
            super.checkValue(val);
        }

        LocalFValueHandle(CodeGenMethodVisitor mv, int offset) {
            super(mv);
            this.offset = offset;
        }
